import{_ as o,y as r,a as s,o as h,a2 as t,D as i}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"AI Image Search","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/image-search.md","filePath":"generative-ai/image-search.md","lastUpdated":1789441803000}'),n={name:"generative-ai/image-search.md"};function d(c,e,l,g,p,u){const a=r("ImagePopup");return h(),s("div",null,[e[0]||(e[0]=t('<h1 id="ai-image-search" tabindex="-1">AI Image Search <a class="header-anchor" href="#ai-image-search" aria-label="Permalink to &quot;AI Image Search&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Storefront</span></div><p>Shoppers can search your catalog with a photo instead of words. With AI image search on, the model you choose looks at the photo and lists what it sees as search keywords, such as the product type, material, color and style. The storefront then shows the matching products. It helps shoppers who don&#39;t know what a product is called.</p><h2 id="where-it-appears" tabindex="-1">Where it appears <a class="header-anchor" href="#where-it-appears" aria-label="Permalink to &quot;Where it appears&quot;">​</a></h2><p>A camera icon sits inside the search bar at the top of the storefront, on desktop and on mobile. It&#39;s shown while <strong>Image Search Option</strong> is switched on under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>, which is the default. See <a href="./../configure/configurable-choices.html">Product Settings</a>.</p>',5)),i(a,{src:"/images/generative-ai/image-search-camera.png",alt:"The storefront search bar with the camera icon for searching with a photo"}),e[1]||(e[1]=t('<h2 id="search-with-a-photo" tabindex="-1">Search with a photo <a class="header-anchor" href="#search-with-a-photo" aria-label="Permalink to &quot;Search with a photo&quot;">​</a></h2><p>This is what a shopper does on the storefront:</p><ol><li>Click the camera icon in the search bar.</li><li>Choose a JPEG, PNG, GIF, WebP or SVG image of up to 2 MB.</li><li>Wait while the photo is analyzed. A spinner replaces the camera icon.</li></ol><p>The search results open for the first keyword. Above the results, the photo is shown beside <strong>Analyzed Keywords:</strong> and the keywords found. The shopper can click another keyword to search for it instead. The keywords go straight to the search, without your review.</p><p>If the file isn&#39;t an image, the shopper sees &quot;Only images (.jpeg, .jpg, .png, ..) are allowed.&quot; If it&#39;s larger than 2 MB, they see &quot;Size Limit Error&quot;. An image in another format, such as a HEIC photo from a phone, shows &quot;Something went wrong, please try again later.&quot;</p><h2 id="with-and-without-ai-image-search" tabindex="-1">With and without AI image search <a class="header-anchor" href="#with-and-without-ai-image-search" aria-label="Permalink to &quot;With and without AI image search&quot;">​</a></h2><p>The camera icon works even when AI image search is off, with a simpler way of recognizing the photo:</p><table tabindex="0"><thead><tr><th></th><th>AI image search on</th><th>AI image search off</th></tr></thead><tbody><tr><td><strong>Who recognizes the photo</strong></td><td>The model you chose, at your AI provider</td><td>A basic recognition model that runs in the shopper&#39;s browser</td></tr><tr><td><strong>What it finds</strong></td><td>Product type, material, color, style, a visible brand and key features</td><td>General names of common objects</td></tr><tr><td><strong>If recognition fails</strong></td><td>The browser model is used instead</td><td>The shopper sees &quot;Something went wrong, please try again later.&quot;</td></tr></tbody></table><h2 id="what-you-control" tabindex="-1">What you control <a class="header-anchor" href="#what-you-control" aria-label="Permalink to &quot;What you control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Image Search Option</strong> under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong></td><td>Shows the camera icon in the search bar</td></tr><tr><td><strong>Enabled</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong></td><td>Switches every Magic AI feature on or off</td></tr><tr><td><strong>Enabled</strong> in the <strong>AI Image Search</strong> section of <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong></td><td>Sends the photo to the AI model, per channel</td></tr><tr><td><strong>Model</strong> in the <strong>AI Image Search</strong> section</td><td>The model that describes the photo, per channel. Choose a model that can read images. With a text-only model, the browser recognition is used instead.</td></tr></tbody></table><p>To set everything up, see <a href="./../configure/magic-ai.html#enable-the-storefront-features">Enable the storefront features</a>.</p><h3 id="photos-leave-your-store" tabindex="-1">Photos leave your store <a class="header-anchor" href="#photos-leave-your-store" aria-label="Permalink to &quot;Photos leave your store&quot;">​</a></h3><p>The photo is uploaded to your store so it can be shown beside the results. With AI image search on, it&#39;s also sent to the provider of the chosen model. If your privacy policy lists the services that process visitor data, add that provider.</p>',13))])}const w=o(n,[["render",d]]);export{f as __pageData,w as default};
